PARAMS = ['R0','kout','Imax','IC50','h']
def predict(df, p):
    def solve_one(dose, ts):
        ts = np.asarray(ts, float)
        kin = p['R0']*p['kout']
        def f(t, y):
            C = dose/50*np.exp(-0.1*t)
            Ch = C**p['h']
            inh = p['Imax']*Ch/(p['IC50']**p['h']+Ch)
            return [kin*(1-inh) - p['kout']*y[0]]
        sol = solve_ivp(f, (0, max(ts.max(),1e-6)), [p['R0']], t_eval=ts, rtol=1e-8, atol=1e-8)
        return sol.y[0]
    return per_dose(df, solve_one)

